"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import TodoForm from "./components/TodoForm";

interface Todo {
  id: number;
  name: string;
  description: string;
  dueDate: string;
  priority: "low" | "medium" | "high";
  completed: boolean;
}

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loaded, setLoaded] = useState(false);


  useEffect(() => {
    const savedTodos = localStorage.getItem("todos");

    if (savedTodos) {
      setTodos(JSON.parse(savedTodos));
    }

    setLoaded(true);
  }, []);


  useEffect(() => {
    if (!loaded) return;

    localStorage.setItem("todos", JSON.stringify(todos));
  }, [todos, loaded]);

  function addTodo(newTodo: Omit<Todo, "completed">) {
    setTodos((prev) => [
      ...prev,
      {
        ...newTodo,
        completed: false,
      },
    ]);
  }

  // function toggleComplete(id: number) {
  //   setTodos((prev) =>
  //     prev.map((todo) =>
  //       todo.id === id
  //         ? { ...todo, completed: !todo.completed }
  //         : todo
  //     )
  //   );
  // }

  // function deleteTodo(id: number) {
  //   setTodos((prev) =>
  //     prev.filter((todo) => todo.id !== id)
  //   );
  // }

  return (
    <main className="min-h-screen bg-grey-100 flex flex-col item-center px-4 py-10">

      <h1 className="text-3xl font-bold text-grey-800 mb-8">
        Add new todo 
      </h1>
      <div>
        
      </div>
        
        <Link href="/todos" className="block w-fit mx-auto mt-6 bg-blue-600 text-white px-4 py-2 rounded-md">
        View Todos
        </Link>
    </main>
  );
}